import{_ as t,o as a,c as o,a0 as r}from"./chunks/framework.lnbZLl6b.js";const n="/projects/aquilifer/screenshots/vault-setup.png",s="/projects/aquilifer/screenshots/vault-unlocked.png",f=JSON.parse('{"title":"The vault","description":"","frontmatter":{},"headers":[],"relativePath":"docs/vault.md","filePath":"docs/vault.md","lastUpdated":1789941056000}'),i={name:"docs/vault.md"};function l(u,e,d,h,c,p){return a(),o("div",null,[...e[0]||(e[0]=[r('<h1 id="the-vault" tabindex="-1">The vault <a class="header-anchor" href="#the-vault" aria-label="Permalink to &quot;The vault&quot;">​</a></h1><p>By default, Aquilifer stores your provider API keys as plain text in the browser&#39;s local storage: sandboxed so no website can ever read it, but not encrypted on disk. The vault is an <strong>optional</strong> upgrade on top of that: a password-protected encryption layer for your stored keys.</p><h2 id="read-this-before-turning-it-on" tabindex="-1">Read this before turning it on <a class="header-anchor" href="#read-this-before-turning-it-on" aria-label="Permalink to &quot;Read this before turning it on&quot;">​</a></h2><p><strong>The vault only encrypts your API keys.</strong> It does not encrypt your <a href="/projects/aquilifer/docs/history">history</a>, your connected-site list, or anything else Aquilifer stores. If you&#39;re picturing &quot;the vault protects my data,&quot; it&#39;s narrower than that: it protects the <em>credential</em>, not what you&#39;ve asked an LLM.</p><p><strong>There is no password recovery.</strong> If you forget your vault password, the API keys it encrypted are permanently unreadable. There&#39;s no reset link, no backend to recover it from: it&#39;s a local encryption key derived from your password, and nobody (including the Aquilifer developers) has a copy of it. If that happens, you&#39;d delete the affected providers and re-add them with a fresh key from your provider&#39;s dashboard. This is an accepted tradeoff, not an oversight: an API key is cheap to rotate, so losing one to a forgotten password is a minor inconvenience, not a disaster.</p><h2 id="why-you-d-turn-it-on" tabindex="-1">Why you&#39;d turn it on <a class="header-anchor" href="#why-you-d-turn-it-on" aria-label="Permalink to &quot;Why you&#39;d turn it on&quot;">​</a></h2><p>The main scenario the vault protects against is a <strong>shared device</strong>: a family computer, a shared work machine, anything where more than one person uses the same browser profile. Without the vault, once a site is connected, anyone using that profile can trigger requests against your API key with no further prompt (that&#39;s the normal, intended &quot;connect once, then silent&quot; behavior; see <a href="/projects/aquilifer/docs/connecting">Connecting a site</a>). With the vault on, the <em>first</em> request after the browser starts pauses for a password unlock; after that, it stays unlocked for the rest of that browser session, so it&#39;s not asking constantly.</p><p>If you&#39;re the only person who ever uses your browser, the vault&#39;s main benefit doesn&#39;t really apply to you: plain storage is already reasonably safe, since a leaked API key is something you can revoke and rotate, unlike, say, a crypto wallet&#39;s private key.</p><h2 id="setting-it-up" tabindex="-1">Setting it up <a class="header-anchor" href="#setting-it-up" aria-label="Permalink to &quot;Setting it up&quot;">​</a></h2><p>From the <strong>Security</strong> tab in settings:</p><p><img src="'+n+'" alt="The Security tab before the vault is set up, with password and confirm password fields and an Enable vault button"></p><ol><li>Choose a password (at least 8 characters) and confirm it.</li><li>Click <strong>Enable vault</strong>. Every API key you&#39;ve already saved gets re-encrypted under it immediately; you don&#39;t need to re-add your providers.</li></ol><p>From then on, adding a new provider requires the vault to be unlocked (the settings page will tell you if it&#39;s locked).</p><h2 id="locking-and-unlocking" tabindex="-1">Locking and unlocking <a class="header-anchor" href="#locking-and-unlocking" aria-label="Permalink to &quot;Locking and unlocking&quot;">​</a></h2><p><img src="'+s+'" alt="The Security tab once the vault is unlocked, showing Lock now and Disable vault buttons"></p><ul><li><strong>Lock now</strong>, in the Security tab, locks it immediately, useful right after using a shared computer.</li><li>It also locks automatically whenever the browser fully closes.</li><li>When something needs a key and the vault is locked, Aquilifer opens a small unlock prompt automatically; enter your password there, and whatever was waiting continues.</li></ul><h2 id="turning-it-off" tabindex="-1">Turning it off <a class="header-anchor" href="#turning-it-off" aria-label="Permalink to &quot;Turning it off&quot;">​</a></h2><p><strong>Disable vault</strong>, also in the Security tab, decrypts everything back to plain storage. You&#39;ll need the vault unlocked to do this, since decrypting back requires the key.</p>',18)])])}const g=t(i,[["render",l]]);export{f as __pageData,g as default};
